'use client';
import { useEffect, useState, useRef, useMemo, FormEvent, ReactNode } from 'react';
import { Activity, ArrowDown, ArrowDownToLine, ArrowRight, ArrowUpRight, Bike, CalendarDays, Check, CheckCheck, ChevronLeft, ChevronRight, CircleHelp, Clock3, CloudCheck, Dumbbell, FileSpreadsheet, Flag, Footprints, Heart, LayoutDashboard, Leaf, LoaderCircle, Menu, MoreHorizontal, Plus, RefreshCw, Settings2, ShieldCheck, Sparkles, Target, TrendingUp, Upload, Utensils, X, Zap, Trash2, Pencil, AlertTriangle, Moon, Droplets, WifiOff } from 'lucide-react';
import PhoneTools from './phone-tools';
import {readLocal,writeLocal,requestPersistentStorage} from '../lib/local-store';
import { State, Session, TrainingLog, StrengthLog, Meal, Checkin, Source, today, addDays, weekStart, sessions, effective, sheetRows, str, num, dateKey, pace, speed, adherence, volume, macrosKcal, proposals, validateSource } from '@/lib/domain';

type View='today'|'calendar'|'training'|'strength'|'nutrition'|'progress'|'adaptive'|'data';
type Modal={type:'training'|'strength'|'meal'|'checkin'|'session'|'import'|'register'|'delete';data?:any}|null;
type Ctx={s:State; date:string; now:string; save:(a:string,d:any)=>Promise<boolean>; open:(m:Modal)=>void; go:(v:View)=>void; select:(d:string)=>void; busy:boolean; error:string};
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
const NAV:{id:View;label:string;icon:any}[]=[{id:'today',label:'Visão geral',icon:LayoutDashboard},{id:'calendar',label:'Calendário',icon:CalendarDays},{id:'training',label:'Treinos',icon:Bike},{id:'strength',label:'Musculação',icon:Dumbbell},{id:'nutrition',label:'Nutrição',icon:Utensils},{id:'progress',label:'Evolução',icon:TrendingUp},{id:'adaptive',label:'Adaptações',icon:Sparkles},{id:'data',label:'Meus dados',icon:FileSpreadsheet}];
const dayNames=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
const dateFmt=(d:string,opt:Intl.DateTimeFormatOptions={day:'2-digit',month:'short'})=>new Date(d+'T12:00:00Z').toLocaleDateString('pt-BR',{...opt,timeZone:'UTC'});
const fmt=(v:number,d=0)=>v.toLocaleString('pt-BR',{maximumFractionDigits:d});
const titleKind=(p:Session)=>/muscula/i.test(p.title)?'strength':/simulado|evento/i.test(p.title)?'brick':/bike/i.test(p.title)?'bike':/corrida/i.test(p.title)?'run':'rest';
const kindLabel:Record<string,string>={run:'Corrida',bike:'Ciclismo',strength:'Musculação',other:'Outra',brick:'Duathlon',rest:'Recuperação'};
const KindIcon=({kind,size=20}:{kind:string;size?:number})=>kind==='strength'?<Dumbbell size={size}/>:kind==='run'?<Footprints size={size}/>:kind==='rest'?<Moon size={size}/>:<Bike size={size}/>;
const Empty=({title,children,icon:Icon=Activity}:{title:string;children?:ReactNode;icon?:any})=><div className="empty"><Icon size={28}/><h3>{title}</h3><p>{children}</p></div>;
const Badge=({children,tone='green'}:{children:ReactNode;tone?:string})=><span className={'badge '+tone}>{children}</span>;
const SectionTitle=({title,sub,action}:{title:string;sub?:string;action?:ReactNode})=><div className="section-title"><div><h2>{title}</h2>{sub&&<p>{sub}</p>}</div>{action}</div>;
const Btn=({children,onClick,secondary=false,disabled=false}:{children:ReactNode;onClick?:()=>void;secondary?:boolean;disabled?:boolean})=><button disabled={disabled} onClick={onClick} className={secondary?'btn secondary':'btn'}>{children}</button>;
const Field=({label,children,hint}:{label:string;children:ReactNode;hint?:string})=><label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;
const Notice=({children,tone='info'}:{children:ReactNode;tone?:string})=><div className={'notice '+tone}><ShieldCheck size={18}/><div>{children}</div></div>;

export default function App(){
  const [s,setS]=useState<State|null>(null),[revision,setRevision]=useState(0),[loaded,setLoaded]=useState(false),[error,setError]=useState(''),[unauth,setUnauth]=useState(false),[busy,setBusy]=useState(false),[view,setView]=useState<View>('today'),[date,setDate]=useState(today()),[now,setNow]=useState(today()),[modal,setModal]=useState<Modal>(null),[toast,setToast]=useState(''),[more,setMore]=useState(false),[savedAt,setSavedAt]=useState(''),[install,setInstall]=useState<any>(null);
  const saving=useRef(false),loadedOnce=useRef(false);
  async function load(){setError('');try{const j=await readLocal();setS(j.state);setRevision(j.revision);setSavedAt(j.updatedAt);const n=today(j.state.settings.timezone);setNow(n);if(!loadedOnce.current){setDate(n);loadedOnce.current=true;}setUnauth(false);}catch(e){setError((e as Error).message);}finally{setLoaded(true);}}
  useEffect(()=>{load();const hash=location.hash.slice(1) as View;if(NAV.some(n=>n.id===hash))setView(hash);const onInstall=(e:any)=>{e.preventDefault();setInstall(e);};window.addEventListener('beforeinstallprompt',onInstall);return()=>window.removeEventListener('beforeinstallprompt',onInstall);},[]);
  useEffect(()=>{const t=setInterval(()=>{if(s)setNow(today(s.settings.timezone));},60000);return()=>clearInterval(t);},[s?.settings.timezone]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t);},[toast]);
  function go(v:View){setView(v);setMore(false);location.hash=v;window.scrollTo({top:0,behavior:'smooth'});}
  async function save(action:string,data:any){if(saving.current)return false;saving.current=true;setBusy(true);setError('');try{const j=await writeLocal(action,data,revision);requestPersistentStorage();setS(j.state);setRevision(j.revision);setSavedAt(j.updatedAt);setToast(action==='decision'?'Decisão salva. Seu planejamento foi atualizado conforme sua escolha.':'Salvo no aparelho.');return true;}catch(e){setError((e as Error).message);return false;}finally{saving.current=false;setBusy(false);}}
  const c:Ctx|undefined=s?{s,date,now,save,open:setModal,go,select:setDate,busy,error}:undefined;
  const pending=s?proposals(s,now).length:0;
  return <div className="app-shell">
    <aside className="sidebar"><a className="brand" href="#today" onClick={e=>{e.preventDefault();go('today');}}>STRIDE<span>↗</span></a><div className="workspace-label">SEU CENTRO DE TREINAMENTO</div><nav aria-label="Navegação principal">{NAV.map((n,i)=><button key={n.id} onClick={()=>go(n.id)} className={`${view===n.id?'active':''} ${i===5?'nav-separator':''}`}><n.icon size={19}/><span>{n.label}</span>{n.id==='adaptive'&&pending>0&&<b className="count">{pending}</b>}</button>)}</nav><div className="sidebar-bottom"><div className="mini-goal"><Flag size={18}/><span>PRÓXIMO OBJETIVO</span><strong>90 + 21,1 km</strong><small>31 de dezembro · 2026</small><div className="hairline"/><Badge tone="amber">Condicionado à prontidão</Badge></div><div className="athlete"><div className="avatar">QS</div><div><strong>Qr Stack</strong><span>Atleta em construção</span></div><ShieldCheck size={17}/></div></div></aside>
    <div className="main-shell"><header className="topbar"><div className="mobile-brand">STRIDE<span>↗</span></div><div className="breadcrumb">Meu treinamento <ChevronRight size={13}/><span>{NAV.find(n=>n.id===view)?.label}</span></div><div className="top-actions"><span className={'sync '+(busy?'syncing':'')} title={savedAt?`Último salvamento neste aparelho: ${new Date(savedAt).toLocaleString('pt-BR')}`:'Conectando ao banco'}><CloudCheck size={16}/>{busy?'Salvando…':s?'Dados salvos':'Conectando'}</span><button className="icon-btn" aria-label="Ajuda e instalação" onClick={()=>go('data')}><CircleHelp size={20}/></button><div className="avatar small">QS</div></div></header>
    <main><div className="page-heading"><div><div className="eyebrow"><span className="tiny-dot"/>{dateFmt(now,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><h1>{view==='today'?'Seu próximo nível.':NAV.find(n=>n.id===view)?.label}</h1><p>{view==='today'?'Consistência hoje. Evolução a cada treino.':view==='calendar'?'Seu planejamento completo, um dia de cada vez.':view==='training'?'O que estava no plano e o que você fez.':view==='strength'?'Mais força para ir além. Peito, costas e ombros em foco.':view==='nutrition'?'Combustível para treinar. Recuperação para evoluir.':view==='progress'?'Seus números, sua trajetória.':view==='adaptive'?'O plano se adapta. A decisão é sempre sua.':'Seu plano e seus registros, sempre com você.'}</p></div><div className="heading-actions"><Btn secondary onClick={()=>setModal({type:'import'})} disabled={!s}><Upload size={16}/><span>Importar planilha</span></Btn><Btn onClick={()=>setModal({type:'register'})} disabled={!s||!sessions(s.source).length}><Plus size={18}/>Registrar</Btn></div></div>
    <PhoneTools install={install} blocked={!!modal||busy}/>
    {error&&<div className="error-banner" role="alert"><AlertTriangle size={19}/><span>{error}</span><button onClick={load} className="text-btn">Recarregar</button><button className="icon-btn" onClick={()=>setError('')} aria-label="Fechar erro"><X size={16}/></button></div>}
    {!loaded?<div className="loading"><LoaderCircle className="spin"/><p>Preparando seu centro de treinamento…</p></div>:unauth?<div className="card auth-card"><ShieldCheck size={36}/><h2>Seu treinamento, em um espaço privado.</h2><p>Entre com sua conta para carregar o plano e salvar seus registros entre dispositivos.</p><a className="btn" href="/signin-with-chatgpt?return_to=/" target="_top">Entrar com ChatGPT <ArrowRight size={17}/></a></div>:!c?<Empty title="Não foi possível carregar o plano"><button className="text-btn" onClick={load}>Tentar novamente</button></Empty>:<>
    {!sessions(c.s.source).length?<section className="card onboarding-plan"><span className="soft-icon green"><FileSpreadsheet size={28}/></span><h2>Seu plano, no seu telefone.</h2><p>Importe a planilha XLSX original ou um backup do STRIDE. A leitura é feita neste aparelho; a planilha e seus registros não são enviados ao GitHub.</p><Btn onClick={()=>setModal({type:'import'})}><Upload size={17}/>Importar meu plano</Btn><p className="muted">Já registrou treinos na versão anterior? Exporte o backup XLSX em Meus dados e importe aqui para transferir o histórico completo.</p></section>:<>{view==='today'&&<Dashboard c={c}/>}{view==='calendar'&&<Calendar c={c}/>}{view==='training'&&<Training c={c}/>}{view==='strength'&&<Strength c={c}/>}{view==='nutrition'&&<Nutrition c={c}/>}{view==='progress'&&<Progress c={c}/>}{view==='adaptive'&&<Adaptive c={c}/>}{view==='data'&&<DataPage c={c} install={install}/>}</>}
    </>}
    <footer className="page-footer"><span>STRIDE · UM DIA DE CADA VEZ</span><span><ShieldCheck size={13}/> Plano original preservado</span></footer></main></div>
    <nav className="mobile-nav" aria-label="Navegação celular">{NAV.filter(n=>['today','calendar','training','nutrition'].includes(n.id)).map(n=><button key={n.id} className={view===n.id?'active':''} onClick={()=>go(n.id)}><n.icon size={21}/><span>{n.id==='today'?'Hoje':n.label}</span></button>)}<button className={more?'active':''} onClick={()=>setMore(!more)}><Menu size={21}/><span>Mais</span></button></nav>
    {more&&<div className="more-menu"><button className="icon-btn close-more" onClick={()=>setMore(false)} aria-label="Fechar menu"><X size={18}/></button>{NAV.filter(n=>['strength','progress','adaptive','data'].includes(n.id)).map(n=><button key={n.id} onClick={()=>go(n.id)}><n.icon size={20}/>{n.label}{n.id==='adaptive'&&pending>0&&<Badge>{pending}</Badge>}</button>)}</div>}
    {modal&&c&&<ModalHost modal={modal} c={c} close={()=>setModal(null)}/>}{toast&&<div className="toast" role="status"><CheckCheck size={19}/>{toast}</div>}
  </div>;
}

function RouteArt(){return <svg className="route-art" viewBox="0 0 430 280" fill="none" aria-hidden="true"><g stroke="#a1c5ac" strokeWidth=".7" opacity=".16">{[0,1,2,3,4,5,6,7].map(i=><path key={i} d={`M${80-i*17} 300 C ${60-i*8} ${210-i*12},${250+i*10} ${255-i*10},${200+i*13} ${120-i*6} S${310+i*16} ${-40+i*4},480 20`}/>)}</g><path d="M65 211 C60 163 146 212 161 161 S103 86 165 66 S259 128 290 97 S309 16 364 37" stroke="#b7d3ad" strokeWidth="25" opacity=".06"/><path d="M65 211 C60 163 146 212 161 161 S103 86 165 66 S259 128 290 97 S309 16 364 37" stroke="#aaca9e" strokeWidth="2.5" strokeDasharray="5 6"/><circle cx="65" cy="211" r="7" fill="#d8ecb8" stroke="#284f42" strokeWidth="4"/><circle cx="364" cy="37" r="17" fill="#d8ecb8"/><path d="M360 45V28M361 29h9l-3 4 3 4h-9" stroke="#173f35" strokeWidth="1.8"/><text x="48" y="240" fill="#bcd0c6" fontSize="10" fontFamily="sans-serif" letterSpacing="2">O CAMINHO É SEU.</text></svg>;}
function Dashboard({c}:{c:Ctx}){
  const {s,now,open,go,select}=c,all=sessions(s.source),todays=all.filter(p=>p.date===now),next=all.find(p=>p.date>now),wk=weekStart(now),week=all.filter(p=>p.date>=wk&&p.date<=addDays(wk,6)),count=adherence(s,wk,now),logs=s.logs.filter(l=>l.date>=wk&&l.date<=now&&l.status==='completed'),planned=week.reduce((a,p)=>a+effective(s,p).minutes,0),real=logs.reduce((a,l)=>a+l.duration,0),rpes=logs.filter(l=>l.rpe!==null),checkin=s.checkins.find(x=>x.date===now),days=Math.max(0,Math.ceil((Date.parse('2026-12-31T12:00:00Z')-Date.parse(now+'T12:00:00Z'))/86400000));
  const nextweek=all.find(p=>p.date>=now)?.week,strip=all.filter(p=>p.week===nextweek).slice(0,7);
  return <><div className="dashboard-top"><div className="goal-hero"><div className="hero-content"><div className="hero-tag"><span className="live-dot"/> PROJETO DUATHLON 2026</div><h2>O desafio é grande.<br/>Sua evolução também.</h2><div className="hero-distances"><div><Bike size={18}/><strong>90<span>km</span></strong><small>CICLISMO</small></div><span className="hero-plus">+</span><div><Footprints size={18}/><strong>21,1<span>km</span></strong><small>CORRIDA</small></div></div><div className="hero-footer"><span><CalendarDays size={15}/>31 dez, 2026</span><span className="hero-condition"><ShieldCheck size={14}/> Meta condicional</span></div></div><RouteArt/><div className="hero-countdown"><strong>{days}</strong><span>DIAS PARA O DESAFIO</span></div></div>
    <div className="card recovery-card"><div className="section-title"><h3>Como você está hoje?</h3><Heart size={19}/></div><p>A recuperação faz parte do treino.</p><div className="recovery-visual"><div className="recovery-ring"><Leaf size={28}/></div><div><strong>{checkin?['','Muito baixa','Baixa','Regular','Boa','Ótima'][checkin.recovery]:'Escute seu corpo'}</strong><span>{checkin?`${fmt(checkin.sleep,1)} h de sono · Dor ${checkin.pain}/10`:'Um check-in rápido antes de começar.'}</span></div></div><Btn secondary onClick={()=>open({type:'checkin'})}>{checkin?<Pencil size={16}/>:<Plus size={16}/>} {checkin?'Atualizar check-in':'Fazer check-in'}</Btn><div className="safe-caption"><ShieldCheck size={13}/> Nenhuma mudança sem sua aprovação</div></div></div>
    <div className="metrics-row"><Metric icon={Clock3} label="VOLUME DA SEMANA" value={fmt(real)} unit="min" detail={`${fmt(planned)} min no planejamento`} color="green"/><Metric icon={CheckCheck} label="ADERÊNCIA ATÉ HOJE" value={count.total?`${count.percent}`:'—'} unit={count.total?'%':''} detail={`${count.done} de ${count.total} sessões previstas`} color="blue"/><Metric icon={Zap} label="ESFORÇO MÉDIO" value={rpes.length?fmt(rpes.reduce((a,l)=>a+l.rpe!,0)/rpes.length,1):'—'} unit={rpes.length?'/10':''} detail={rpes.length?`${rpes.length} registros nesta semana`:'Aguardando seu primeiro registro'} color="orange"/><Metric icon={Dumbbell} label="FOCO DE HIPERTROFIA" value="Superiores" detail="Peito · Costas · Ombros" color="purple" text/></div>
    <div className="dashboard-columns"><div className="dashboard-main"><section className="card"><SectionTitle title="Sua semana, em movimento" sub={strip.length?`${dateFmt(strip[0].date)} — ${dateFmt(strip[strip.length-1].date)} · ${nextweek}`:'Nenhum treino futuro no plano'} action={<button className="text-btn" onClick={()=>{select(strip[0]?.date||now);go('calendar');}}>Ver calendário <ArrowUpRight size={15}/></button>}/><div className="week-strip">{strip.map(p=><button key={p.id} onClick={()=>{select(p.date);open({type:'session',data:p});}} className={'week-day '+(p.date===now?'is-today':'')}><span>{p.day.toUpperCase()}</span><strong>{p.date.slice(-2)}</strong><span className={'day-symbol '+titleKind(p)}><KindIcon kind={titleKind(p)} size={18}/></span><small>{titleKind(p)==='rest'?'Livre':titleKind(p)==='strength'?'Força':titleKind(p)==='brick'?'Brick':kindLabel[titleKind(p)]}</small>{s.logs.some(l=>l.sessionId===p.id&&l.status==='completed')&&<Check className="day-check" size={13}/>}</button>)}</div><div className="week-legend"><span><i className="legend-dot run"/>Corrida</span><span><i className="legend-dot bike"/>Ciclismo</span><span><i className="legend-dot strength"/>Força</span><span><i className="legend-dot brick"/>Duathlon</span></div></section>
    <section><SectionTitle title="Seu treino de hoje" sub={dateFmt(now,{weekday:'long',day:'numeric',month:'long'})}/>{todays.length?todays.map(p=><SessionCard key={p.id} p={p} c={c}/>):<div className="card no-today"><div className="session-icon rest"><Moon size={23}/></div><div><Badge tone="neutral">{now<all[0]?.date?'ANTES DO INÍCIO':'SEM SESSÃO PRESCRITA'}</Badge><h3>{now<all[0]?.date?'A preparação começa agora.':'Hoje não há treino no calendário.'}</h3><p>{next?`Seu próximo treino está marcado para ${dateFmt(next.date)}.`:'Consulte o histórico ou registre uma atividade extra.'}</p></div></div>}{!todays.length&&next&&<><div className="next-caption">PRÓXIMA SESSÃO · {dateFmt(next.date).toUpperCase()}</div><SessionCard p={next} c={c}/></>}</section>
    <section className="card"><SectionTitle title="Planejamento × realizado" sub="Duração de todas as modalidades · minutos" action={<button className="text-btn" onClick={()=>go('progress')}>Evolução <ArrowUpRight size={15}/></button>}/><WeeklyChart s={s} start={wk}/></section></div>
    <aside className="dashboard-aside"><section className="card fuel-card"><div className="section-title"><div className="icon-heading"><span className="soft-icon amber"><Utensils size={18}/></span><h3>Combustível do dia</h3></div><button className="icon-btn" aria-label="Ver nutrição" onClick={()=>{select(now);go('nutrition');}}><ArrowUpRight size={18}/></button></div><DailyNutrition s={s} date={now} compact/><Btn secondary onClick={()=>{select(now);open({type:'meal'});}}><Plus size={16}/> Registrar refeição</Btn></section>
    <section className="card adaptive-mini"><div className="icon-heading"><span className="soft-icon green"><Sparkles size={18}/></span><h3>Treino com inteligência</h3></div><p>{proposals(s,now).length?'Há uma proposta de ajuste aguardando sua revisão.':'Seu plano evolui a partir dos seus registros e da sua recuperação.'}</p><div className="mini-rule"><Check size={15}/> Sexta e sábado só musculação</div><div className="mini-rule"><Check size={15}/> Domingos de simulado progressivo</div><div className="mini-rule"><Check size={15}/> Ciclismo preservado · {s.settings.stiRepaired?'STI reparado':'STI pendente'}</div><button className="text-btn" onClick={()=>go('adaptive')}>Ver adaptações <ArrowRight size={15}/></button></section><div className="quote"><span>“</span><p>O próximo passo<br/>é o que faz a diferença.</p><small>SEU RITMO. SUA JORNADA.</small></div></aside></div>
  </>;
}
function Metric({icon:Icon,label,value,unit,detail,color,text=false}:any){return <div className="metric"><div className="metric-label">{label}<span className={'soft-icon '+color}><Icon size={17}/></span></div><strong className={text?'text-value':''}>{value}<span>{unit}</span></strong><small>{detail}</small></div>;}
function SessionCard({p,c}:{p:Session;c:Ctx}){const e=effective(c.s,p),kind=titleKind(p),logs=c.s.logs.filter(l=>l.sessionId===p.id),done=adherence(c.s,p.date,p.date),status=logs.some(l=>l.status==='completed'),future=p.date>c.now;return <article className={'session-card card '+kind}><div className="session-top"><span className={'session-icon '+kind}><KindIcon kind={kind} size={24}/></span><div className="session-heading"><div className="session-tags"><Badge tone={kind==='run'?'blue':kind==='strength'?'purple':kind==='rest'?'neutral':'green'}>{p.week} · {kindLabel[kind]}</Badge>{e.factor!==1&&<Badge tone="amber">Ajuste aprovado</Badge>}{status&&<Badge>{done.done?'Concluído':'Registro parcial'}</Badge>}</div><h3>{p.title}</h3></div><button className="icon-btn" aria-label={`Detalhes de ${p.title}`} onClick={()=>c.open({type:'session',data:p})}><MoreHorizontal size={20}/></button></div><p className="prescription">{e.factor!==1&&<strong>Prescrição original: </strong>}{p.prescription}</p>{p.strength&&p.strength!=='—'&&<p className="strength-note"><Dumbbell size={15}/>{p.strength}</p>}<div className="session-metrics">{e.bikeKm!==null&&<span><Bike size={15}/><strong>{fmt(e.bikeKm,1)} km</strong></span>}{e.runKm!==null&&<span><Footprints size={15}/><strong>{fmt(e.runKm,2)} km</strong>{e.factor!==1?' ajustado':''}</span>}{e.minutes>0&&<span><Clock3 size={15}/><strong>{e.minutes} min</strong></span>}{p.pace&&e.factor>=1&&<span><Zap size={15}/><strong>{p.pace}</strong> /km</span>}</div>{e.factor>0&&e.factor!==1&&<Notice tone="warning"><strong>Ajuste aprovado em vigor:</strong> {e.minutes} min{e.runKm!==null?` · ${fmt(e.runKm,2)} km de corrida`:""}.{e.factor<1?" Manter esforço leve e conversável, sem perseguir os tiros ou paces da fonte original.":" Manter o pace fácil original; não acelerar para compensar o volume."}</Notice>}{e.factor===0&&<Notice tone="danger">Sessão pausada por ajuste aprovado. Prescrição original mantida acima para consulta.</Notice>}<div className="session-bottom"><span>{e.factor<1?(e.factor===0?'Pausa aprovada · reavaliar antes de retomar':'Volume reduzido · esforço confortável'):p.intensity}</span>{kind==='rest'?<button className="text-btn" onClick={()=>c.open({type:'checkin'})}>Check-in <ArrowRight size={15}/></button>:<button className="btn small-btn" onClick={()=>{c.select(p.date);c.open({type:'training',data:{session:p}});}}><Plus size={15}/>{future?'Registrar nesta data':'Registrar treino'}</button>}</div></article>;}
function DatePicker({c}:{c:Ctx}){return <div className="date-picker"><button className="icon-btn" aria-label="Dia anterior" onClick={()=>c.select(addDays(c.date,-1))}><ChevronLeft size={19}/></button><input aria-label="Data selecionada" type="date" value={c.date} onChange={e=>e.target.value&&c.select(e.target.value)}/><button className="icon-btn" aria-label="Próximo dia" onClick={()=>c.select(addDays(c.date,1))}><ChevronRight size={19}/></button><button className="text-btn" onClick={()=>c.select(c.now)}>Hoje</button></div>;}

function Calendar({c}:{c:Ctx}){const [mode,setMode]=useState('month'),[month,setMonth]=useState(c.date.slice(0,7));const all=sessions(c.s.source),start=mode==='week'?weekStart(c.date):weekStart(month+'-01');let days=Array.from({length:mode==='week'?7:42},(_,i)=>addDays(start,i));function move(n:number){if(mode==='week')c.select(addDays(c.date,n*7));else{const d=new Date(month+'-15T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+n);setMonth(d.toISOString().slice(0,7));}}return <div className="calendar-layout"><section className="card calendar-card"><div className="calendar-toolbar"><div className="calendar-month"><button className="icon-btn" aria-label="Período anterior" onClick={()=>move(-1)}><ChevronLeft size={19}/></button><h2>{mode==='week'?`${dateFmt(start)} — ${dateFmt(addDays(start,6))}`:dateFmt(month+'-15',{month:'long',year:'numeric'})}</h2><button className="icon-btn" aria-label="Próximo período" onClick={()=>move(1)}><ChevronRight size={19}/></button></div><div className="segmented"><button className={mode==='week'?'active':''} onClick={()=>setMode('week')}>Semana</button><button className={mode==='month'?'active':''} onClick={()=>setMode('month')}>Mês</button></div><button className="text-btn" onClick={()=>{setMonth(c.now.slice(0,7));c.select(c.now);}}>Hoje</button></div><div className="calendar-grid day-headers">{dayNames.map(d=><div key={d}>{d}</div>)}</div><div className={'calendar-grid dates '+(mode==='week'?'weekly':'')}>{days.map(d=>{const ps=all.filter(p=>p.date===d),done=c.s.logs.some(l=>l.date===d&&l.status==='completed');return <button key={d} className={'calendar-cell '+(d===c.date?'selected ':'')+(d===c.now?'today-cell ':'')+(mode==='month'&&d.slice(0,7)!==month?'muted-cell':'')} onClick={()=>c.select(d)}><span className="cell-date">{num(d.slice(-2))}{done&&<Check size={12}/>}</span>{ps.map(p=><span key={p.id} className={'cal-event '+titleKind(p)}><KindIcon kind={titleKind(p)} size={12}/><span>{p.title}</span></span>)}</button>;})}</div><div className="week-legend"><span><i className="legend-dot run"/>Corrida</span><span><i className="legend-dot bike"/>Bike</span><span><i className="legend-dot strength"/>Força</span><span><i className="legend-dot brick"/>Duathlon</span></div></section><section className="calendar-detail"><SectionTitle title={dateFmt(c.date,{weekday:'long',day:'numeric',month:'long'})} sub={c.date<c.now?'Histórico do planejamento':'Planejamento do dia'}/>{all.filter(p=>p.date===c.date).map(p=><SessionCard key={p.id} p={p} c={c}/>)}{!all.some(p=>p.date===c.date)&&<div className="card"><Empty title="Nenhuma sessão nesta data" icon={CalendarDays}>Você pode registrar uma atividade extra.</Empty><Btn secondary onClick={()=>c.open({type:'training'})}><Plus size={16}/> Registrar atividade</Btn></div>}<div className="card"><SectionTitle title="Nutrição do dia"/><DailyNutrition s={c.s} date={c.date} compact/></div><div className="card"><SectionTitle title="Registros realizados"/>{c.s.logs.filter(l=>l.date===c.date).length?<LogList c={c} logs={c.s.logs.filter(l=>l.date===c.date)}/>:<p className="muted">Nenhum treino registrado nesta data.</p>}</div></section></div>;}

function Training({c}:{c:Ctx}){const [filter,setFilter]=useState('all'),[query,setQuery]=useState(''),[tab,setTab]=useState('planned');const list=sessions(c.s.source).filter(p=>p.date===c.date);const logs=c.s.logs.filter(l=>(filter==='all'||l.kind===filter)&&(!query||[l.notes,l.date,kindLabel[l.kind]].join(' ').toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));return <><div className="section-controls"><DatePicker c={c}/><div className="segmented"><button className={tab==='planned'?'active':''} onClick={()=>setTab('planned')}>Planejamento</button><button className={tab==='history'?'active':''} onClick={()=>setTab('history')}>Histórico completo</button></div></div>{tab==='planned'?<><div className="two-column">{list.map(p=><SessionCard key={p.id} p={p} c={c}/>)}{!list.length&&<div className="card"><Empty title="Sem sessão prescrita" icon={Bike}>Use o calendário para escolher outro dia.</Empty><Btn onClick={()=>c.open({type:'training'})}><Plus size={16}/> Registrar atividade extra</Btn></div>}<div className="card"><SectionTitle title="Realizado nesta data" action={<button className="text-btn" onClick={()=>c.open({type:'training'})}><Plus size={16}/>Registro</button>}/><LogList c={c} logs={c.s.logs.filter(l=>l.date===c.date)}/></div></div></>:<div className="card"><div className="history-filter"><input aria-label="Buscar registros" placeholder="Buscar por data, modalidade ou observação…" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="Filtrar modalidade" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Todas as modalidades</option><option value="run">Corrida</option><option value="bike">Ciclismo</option><option value="strength">Musculação</option><option value="other">Outra</option></select></div><LogList c={c} logs={logs}/></div>}</>;}
function LogList({c,logs}:{c:Ctx;logs:TrainingLog[]}){if(!logs.length)return <Empty title="Cada treino conta" icon={Activity}>Registre sua primeira atividade para acompanhar a evolução.</Empty>;return <div className="log-list">{logs.map(l=><div className="log-item" key={l.id}><span className={'soft-icon '+(l.kind==='run'?'blue':'green')}><KindIcon kind={l.kind}/></span><div className="log-body"><strong>{kindLabel[l.kind]} <small>{dateFmt(l.date)}</small></strong><span>{l.status==='skipped'?'Não realizado':`${fmt(l.distance,2)} km · ${fmt(l.duration,1)} min${l.kind==='run'?` · ${pace(l.distance,l.duration)}/km`:l.kind==='bike'?` · ${fmt(speed(l.distance,l.duration),1)} km/h`:''}`}</span><small>{l.rpe!==null?`RPE ${l.rpe}/10 · `:''}{l.hr?`${l.hr} bpm · `:''}Dor {l.pain}/10</small>{l.notes&&<p>{l.notes}</p>}</div><div className="log-actions"><button className="icon-btn" aria-label="Editar treino" onClick={()=>c.open({type:'training',data:{log:l}})}><Pencil size={15}/></button><button className="icon-btn" aria-label="Excluir treino" onClick={()=>c.open({type:'delete',data:{collection:'logs',id:l.id,label:'este registro de treino'}})}><Trash2 size={15}/></button></div></div>)}</div>;}

function Strength({c}:{c:Ctx}){const rows=sheetRows(c.s.source,'Musculacao').slice(1).filter(r=>r.some(x=>x!==null)),day=dayNames[new Date(c.date+'T12:00:00Z').getUTCDay()],planned=rows.filter(r=>r[0]===day),logs=c.s.strength.filter(l=>l.date===c.date),[routine,setRoutine]=useState('date');const shown=routine==='date'?planned:rows.filter(r=>r[0]===routine);return <><div className="section-controls"><DatePicker c={c}/><Btn onClick={()=>c.open({type:'strength'})}><Plus size={17}/> Registrar exercício</Btn></div><div className="two-column strength-columns"><section className="card"><SectionTitle title="Sua rotina de força" sub="Peito, costas e ombros · prescrição original"/><div className="segmented routine-tabs">{[['date','Neste dia'],['Sex','Treino A'],['Sáb','Treino B'],['Ter','Pernas']].map(([v,l])=><button key={v} onClick={()=>setRoutine(v)} className={routine===v?'active':''}>{l}</button>)}</div>{shown.length?shown.map((r,i)=>{const last=c.s.strength.filter(l=>l.exercise===r[1]&&l.date<=c.date).sort((a,b)=>b.date.localeCompare(a.date))[0];return <div className="exercise-row" key={i}><span className="exercise-index">{String(i+1).padStart(2,'0')}</span><div><h3>{r[1]}</h3><span>{r[2]} séries × {r[3]} reps</span><small>{r[4]} · Descanso {r[5]}</small>{last&&<small className="green-text">Último: {last.sets.map(s=>`${s.reps}×${s.kg} kg`).join(' · ')} ({dateFmt(last.date)})</small>}</div><button className="icon-btn circle-btn" aria-label={`Registrar ${r[1]}`} onClick={()=>c.open({type:'strength',data:{exercise:r}})}><Plus size={18}/></button></div>;}):<Empty title="Sem musculação prescrita hoje" icon={Dumbbell}>As rotinas estão nas abas Treino A, Treino B e Pernas.</Empty>}<Notice>Evite falha sistemática e fadiga excessiva antes do simulado de domingo. As séries e os RIR originais foram preservados.</Notice></section><div><section className="card"><SectionTitle title="Séries realizadas" sub={dateFmt(c.date,{day:'numeric',month:'long'})}/>{logs.length?logs.map(l=><div className="exercise-record" key={l.id}><div><strong>{l.exercise}</strong><small>{l.sets.map(x=>`${x.reps} × ${fmt(x.kg,1)} kg`).join(' · ')}</small><span>{fmt(volume(l))} kg de volume</span>{l.notes&&<p>{l.notes}</p>}</div><div className="log-actions"><button className="icon-btn" aria-label="Editar exercício" onClick={()=>c.open({type:'strength',data:{log:l}})}><Pencil size={15}/></button><button className="icon-btn" aria-label="Excluir exercício" onClick={()=>c.open({type:'delete',data:{collection:'strength',id:l.id,label:'este exercício registrado'}})}><Trash2 size={15}/></button></div></div>):<Empty title="Vamos construir sua evolução" icon={Dumbbell}>Preencha repetições e carga de cada série.</Empty>}<Btn secondary onClick={()=>c.open({type:'training',data:{session:sessions(c.s.source).find(p=>p.date===c.date&&/muscula/i.test(p.title)),kind:'strength'}})}><CheckCheck size={16}/> Concluir sessão de musculação</Btn></section><section className="card spaced"><SectionTitle title="Evolução de cargas" sub="Consulte máximas e volume por exercício."/><button className="text-btn" onClick={()=>c.go('progress')}>Abrir evolução <ArrowRight size={16}/></button></section></div></div></>;}

function DailyNutrition({s,date,compact=false}:{s:State;date:string;compact?:boolean}){const rows=sheetRows(s.source,'Nutricao por Data').slice(1).filter(r=>dateKey(r[0])===date);return rows.length?<div className={'daily-nutrition '+(compact?'compact':'')}>{rows.map((r,i)=><div key={i}>{!compact&&<Badge tone="amber">{r[2]} · {r[3]}</Badge>}{[['PRÉ-TREINO',r[4]],['DURANTE O TREINO',r[5]],['PÓS-TREINO',r[6]]].map(([l,v],j)=><div className="fuel-step" key={l}><span className="step-number">{String(j+1).padStart(2,'0')}</span><div><small>{l}</small><p>{v}</p></div></div>)}</div>)}<span className="source-caption">Orientações existentes na planilha</span></div>:<p className="muted no-nutrition">Sem orientação nutricional prescrita para esta data. Consulte o calendário e a dieta original.</p>;}
function Nutrition({c}:{c:Ctx}){const meals=c.s.meals.filter(m=>m.date===c.date),tot=meals.reduce((a,m)=>({protein:a.protein+m.protein,carbs:a.carbs+m.carbs,fat:a.fat+m.fat,kcal:a.kcal+(m.calories??macrosKcal(m)),water:a.water+m.water}),{protein:0,carbs:0,fat:0,kcal:0,water:0}),diet=sheetRows(c.s.source,'Dieta Original e Ajustes').slice(1),[dietTab,setDietTab]=useState('training');return <><div className="section-controls"><DatePicker c={c}/><Btn onClick={()=>c.open({type:'meal'})}><Plus size={17}/> Registrar refeição</Btn></div><div className="metrics-row nutrition-metrics"><Metric icon={Zap} label="ENERGIA REGISTRADA" value={fmt(tot.kcal)} unit="kcal" detail="Valor informado ou cálculo 4/4/9" color="orange"/><Metric icon={Dumbbell} label="PROTEÍNAS" value={fmt(tot.protein,1)} unit="g" detail="Soma das refeições registradas" color="green"/><Metric icon={Leaf} label="CARBOIDRATOS" value={fmt(tot.carbs,1)} unit="g" detail={`${fmt(tot.fat,1)} g de gorduras registrados`} color="purple"/><Metric icon={Droplets} label="HIDRATAÇÃO" value={fmt(tot.water)} unit="mL" detail="Quantidade informada por você" color="blue"/></div><div className="two-column"><section className="card"><SectionTitle title="Abastecimento do dia" sub="Transcrição do planejamento nutricional"/><DailyNutrition s={c.s} date={c.date}/><Notice>As orientações importadas são mantidas como referência. Alterar calorias, metas de macros, suplementos ou estratégia de prova depende de validação profissional.</Notice></section><section className="card"><SectionTitle title="Seu diário alimentar" sub={`${meals.length} refeições nesta data`}/>{meals.length?meals.map(m=><div className="meal-record" key={m.id}><div className="meal-top"><div><Badge tone="amber">{m.timing}</Badge><h3>{m.name}</h3></div><div className="log-actions"><button className="icon-btn" aria-label="Editar refeição" onClick={()=>c.open({type:'meal',data:m})}><Pencil size={15}/></button><button className="icon-btn" aria-label="Excluir refeição" onClick={()=>c.open({type:'delete',data:{collection:'meals',id:m.id,label:'esta refeição'}})}><Trash2 size={15}/></button></div></div><div className="meal-macros"><strong>{fmt(m.calories??macrosKcal(m))} kcal</strong><span>P {fmt(m.protein,1)} g</span><span>C {fmt(m.carbs,1)} g</span><span>G {fmt(m.fat,1)} g</span></div><small>{m.calories!==null?'Calorias informadas por você':'Calorias calculadas: proteína ×4 + carbo ×4 + gordura ×9'} · {m.water} mL</small>{m.gi&&<p>Sintomas GI: {m.gi}</p>}{m.notes&&<p>{m.notes}</p>}</div>):<Empty title="Seu combustível também conta" icon={Utensils}>Registre alimentos, macros e o que funcionou no pré e no intra-treino.</Empty>}</section></div><section className="card spaced"><SectionTitle title="Dieta original e pontos para revisão" sub="Alimentos preservados. Revisões separadas para conversar com seu nutricionista."/><div className="segmented"><button className={dietTab==='training'?'active':''} onClick={()=>setDietTab('training')}>Dia de treino</button><button className={dietTab==='rest'?'active':''} onClick={()=>setDietTab('rest')}>Descanso</button></div><div className="table-scroll"><table><thead><tr><th>Horário</th><th>Alimentos do plano original</th><th>Observação original</th><th>Requer validação profissional</th></tr></thead><tbody>{diet.filter(r=>dietTab==='training'?r[0]==='Dia de treino':r[0]!=='Dia de treino').map((r,i)=><tr key={i}><td><strong>{r[1]}</strong><small>{r[0]}</small></td><td>{r[2]}</td><td>{r[3]}</td><td><span className="review-note">{r[4]}</span></td></tr>)}</tbody></table></div></section></>;}

function WeeklyChart({s,start}:{s:State;start:string}){const all=sessions(s.source),rows=Array.from({length:7},(_,i)=>{const date=addDays(start,i);return {date,planned:all.filter(p=>p.date===date).reduce((a,p)=>a+effective(s,p).minutes,0),actual:s.logs.filter(l=>l.date===date&&l.status==='completed').reduce((a,l)=>a+l.duration,0)};}),max=Math.max(60,...rows.flatMap(r=>[r.planned,r.actual]));return <div className="weekly-chart"><div className="chart-legend"><span><i style={{background:'#dce6df'}}/>Planejado</span><span><i style={{background:'#28775b'}}/>Realizado</span></div><svg viewBox="0 0 640 180" role="img" aria-label="Duração semanal planejada e realizada em minutos">{[0,.5,1].map(k=><g key={k}><line x1="32" x2="630" y1={145-k*120} y2={145-k*120} stroke="#e9ece7" strokeDasharray="3 4"/><text x="24" y={149-k*120} textAnchor="end" fill="#8a938c" fontSize="10">{Math.round(max*k)}</text></g>)}{rows.map((r,i)=>{const x=55+i*84;return <g key={r.date}><title>{dateFmt(r.date)}: planejado {r.planned} min, realizado {r.actual} min</title><rect x={x} y={145-r.planned/max*120} width="19" height={r.planned/max*120} fill="#dce6df" rx="4"/><rect x={x+23} y={145-r.actual/max*120} width="19" height={r.actual/max*120} fill="#28775b" rx="4"/><text x={x+20} y="168" textAnchor="middle" fill="#7a847d" fontSize="11">{dayNames[i]}</text></g>;})}</svg><small className="chart-caption">{dateFmt(start)} — {dateFmt(addDays(start,6))}{!s.logs.some(l=>l.date>=start&&l.date<=addDays(start,6))?' · Ainda sem registros realizados':''}</small></div>;}
function LineChart({rows,unit,color='#28775b',label}:{rows:{date:string;value:number}[];unit:string;color?:string;label:string}){if(!rows.length)return <Empty title="A evolução começa com o primeiro registro" icon={TrendingUp}>Os gráficos serão construídos com seus dados reais.</Empty>;const max=Math.max(...rows.map(r=>r.value),1),min=Math.min(0,...rows.map(r=>r.value)),range=max-min||1,points=rows.map((r,i)=>[40+(rows.length===1?250:i/(rows.length-1)*520),145-(r.value-min)/range*115]);return <><svg className="line-chart" viewBox="0 0 600 185" role="img" aria-label={label}>{[0,.5,1].map(k=><g key={k}><line x1="40" x2="570" y1={145-k*115} y2={145-k*115} stroke="#e5e9e3"/><text x="33" y={149-k*115} textAnchor="end" fill="#8a938c" fontSize="10">{fmt(min+range*k,1)}</text></g>)}<polyline points={points.map(p=>p.join(',')).join(' ')} stroke={color} fill="none" strokeWidth="2.5"/>{points.map(([x,y],i)=><g key={i}><circle cx={x} cy={y} r="4" fill={color}><title>{dateFmt(rows[i].date)}: {fmt(rows[i].value,2)} {unit}</title></circle>{(i===0||i===points.length-1)&&<text x={x} y="170" textAnchor="middle" fontSize="11" fill="#7a847d">{dateFmt(rows[i].date)}</text>}</g>)}</svg><details className="chart-values"><summary>Ver valores · {unit}</summary><div className="table-scroll"><table><thead><tr><th>Data</th><th>{label}</th></tr></thead><tbody>{rows.map((r,i)=><tr key={i}><td>{dateFmt(r.date,{day:'2-digit',month:'2-digit',year:'numeric'})}</td><td>{fmt(r.value,2)} {unit}</td></tr>)}</tbody></table></div></details></>;}
function Progress({c}:{c:Ctx}){const [range,setRange]=useState('30'),[sport,setSport]=useState('run'),[metric,setMetric]=useState('distance'),[exercise,setExercise]=useState('Supino reto'),[week,setWeek]=useState(weekStart(c.now));const start=range==='all'?'1900-01-01':addDays(c.now,-Number(range)+1),logs=c.s.logs.filter(l=>l.date>=start&&l.date<=c.now&&l.status==='completed'),selected=logs.filter(l=>l.kind===sport).sort((a,b)=>a.date.localeCompare(b.date)),values=selected.filter(l=>metric==='hr'?l.hr!==null:metric==='rpe'?l.rpe!==null:metric==='pace'||metric==='speed'?l.distance>0&&l.duration>0:true).map(l=>({date:l.date,value:metric==='distance'?l.distance:metric==='duration'?l.duration:metric==='pace'?l.duration/l.distance:metric==='speed'?speed(l.distance,l.duration):metric==='rpe'?l.rpe!:l.hr!})),strength=c.s.strength.filter(l=>l.date>=start&&l.date<=c.now&&l.exercise===exercise).sort((a,b)=>a.date.localeCompare(b.date)),exercises=Array.from(new Set([...sheetRows(c.s.source,'Musculacao').slice(1).map(r=>str(r[1])),...c.s.strength.map(l=>l.exercise)])).filter(Boolean),adh=adherence(c.s,start,c.now);const weeks=Array.from({length:Math.min(12,range==='all'?12:Math.ceil(Number(range)/7))},(_,i)=>addDays(weekStart(c.now),-7*i)).reverse();return <><div className="section-controls"><span className="muted">Somente dados registrados até hoje.</span><select aria-label="Período dos gráficos" value={range} onChange={e=>setRange(e.target.value)}><option value="7">Últimos 7 dias</option><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option><option value="all">Todo o histórico</option></select></div><div className="metrics-row"><Metric icon={Activity} label="ATIVIDADES" value={logs.length} detail="Registros realizados no período" color="green"/><Metric icon={Clock3} label="TEMPO TOTAL" value={fmt(logs.reduce((a,l)=>a+l.duration,0)/60,1)} unit="h" detail="Todas as modalidades" color="blue"/><Metric icon={Footprints} label="CORRIDA" value={fmt(logs.filter(l=>l.kind==='run').reduce((a,l)=>a+l.distance,0),1)} unit="km" detail="Distância realizada" color="orange"/><Metric icon={CheckCheck} label="ADERÊNCIA" value={adh.total?adh.percent:'—'} unit={adh.total?'%':''} detail={`${adh.done} de ${adh.total} sessões até hoje`} color="purple"/></div><div className="two-column"><section className="card"><SectionTitle title="Desempenho ao longo do tempo"/><div className="chart-controls"><select aria-label="Modalidade do gráfico" value={sport} onChange={e=>{setSport(e.target.value);if(metric==='pace'||metric==='speed')setMetric('distance');}}><option value="run">Corrida</option><option value="bike">Ciclismo</option></select><select aria-label="Métrica do gráfico" value={metric} onChange={e=>setMetric(e.target.value)}><option value="distance">Distância · km</option><option value="duration">Duração · min</option>{sport==='run'?<option value="pace">Pace · min/km</option>:<option value="speed">Velocidade · km/h</option>}<option value="hr">Frequência cardíaca · bpm</option><option value="rpe">Esforço · RPE</option></select></div><LineChart rows={values} unit={{distance:'km',duration:'min',pace:'min/km (decimal)',speed:'km/h',hr:'bpm',rpe:'/10'}[metric]||''} label={`${kindLabel[sport]} · ${metric}`}/></section><section className="card"><SectionTitle title="Força em evolução" sub="Carga máxima e volume por exercício"/><select aria-label="Exercício do gráfico" value={exercise} onChange={e=>setExercise(e.target.value)}>{exercises.map(x=><option key={x}>{x}</option>)}</select><LineChart rows={strength.map(l=>({date:l.date,value:Math.max(...l.sets.map(s=>s.kg))}))} unit="kg" label="Carga máxima registrada" color="#8472af"/>{strength.length>0&&<div className="strength-stat"><span>Volume da última sessão</span><strong>{fmt(volume(strength[strength.length-1]))} kg</strong></div>}</section><section className="card"><SectionTitle title="Volume semanal" sub="Minutos planejados × realizados" action={<div className="inline-actions"><button className="icon-btn" aria-label="Semana anterior" onClick={()=>setWeek(addDays(week,-7))}><ChevronLeft size={17}/></button><button className="icon-btn" aria-label="Próxima semana" onClick={()=>setWeek(addDays(week,7))}><ChevronRight size={17}/></button></div>}/><WeeklyChart s={c.s} start={week}/></section><section className="card"><SectionTitle title="Consistência por semana" sub="Percentual de sessões integralmente realizadas"/><LineChart rows={weeks.filter(date=>adherence(c.s,date,addDays(date,6)>c.now?c.now:addDays(date,6)).total>0).map(date=>({date,value:adherence(c.s,date,addDays(date,6)>c.now?c.now:addDays(date,6)).percent}))} unit="%" label="Aderência"/><small className="muted">Brick exige registro de bike e corrida. Terças com pernas exigem também o registro de musculação. Atividades futuras não entram no cálculo.</small></section></div></>;}

function Adaptive({c}:{c:Ctx}){const ps=proposals(c.s,c.now),rules=sheetRows(c.s.source,'Regras e Prontidao').slice(1),runMax=Math.max(0,...c.s.logs.filter(l=>l.kind==='run'&&l.status==='completed'&&l.date<=c.now).map(l=>l.distance)),bikeMax=Math.max(0,...c.s.logs.filter(l=>l.kind==='bike'&&l.status==='completed'&&l.date<=c.now).map(l=>l.distance));return <><Notice>A meta de 31/12 exige prontidão específica e liberação clínica. O app usa regras conservadoras de acompanhamento e não emite liberação médica. Dor torácica, desmaio, confusão ou crise exigem interrupção e avaliação conforme a gravidade.</Notice><div className="two-column spaced"><section className="card"><SectionTitle title="Propostas para sua revisão" sub="Nenhuma carga muda sem um clique em aprovar."/>{ps.length?ps.map(p=>{const session=sessions(c.s.source).find(s=>s.id===p.sessionId)!;return <div className={'proposal '+p.level} key={p.id}><Badge tone={p.level==='danger'?'red':'amber'}>{p.level==='danger'?'Recuperação primeiro':'Sugestão de ajuste'}</Badge><h3>{p.title}</h3><p>{p.reason}</p><div className="proposal-change"><span>{dateFmt(p.date)} · {session.title}</span><strong>{session.minutes} min <ArrowRight size={15}/> {Math.round(session.minutes*p.factor)} min</strong></div><small>O original é mantido. Paces não são acelerados. Ciclismo e simulados permanecem preservados.</small><div className="form-actions"><Btn secondary disabled={c.busy} onClick={()=>c.save('decision',{id:p.id,status:'rejected'})}>Recusar</Btn><Btn disabled={c.busy} onClick={()=>c.save('decision',{id:p.id,status:'approved'})}><Check size={16}/>Aprovar alteração</Btn></div></div>;}):<Empty title="Sem mudanças propostas agora" icon={ShieldCheck}>Continue registrando treino, dor e recuperação. Ausência de proposta não significa liberação para treinar com sintomas.</Empty>}<div className="rule-explanation"><h3>Como as regras funcionam</h3><p>Dor ≥4/10 ou alerta recente: propor pausa na próxima corrida. Sono &lt;6 h, recuperação ≤2/5 ou RPE ≥8: propor 20% menos volume.</p><p>Um acréscimo de até 5% no longão só pode ser proposto após duas semanas documentadas, sem dor, recuperação consistente e aderência ≥80%. Sem acréscimos nas descargas nem a partir de 13/12. Não há aumento de peso de musculação ou prescrição nutricional automática.</p></div></section><div><section className="card"><SectionTitle title="Condições do planejamento"/><label className="toggle-field"><div><strong>Reparo do STI concluído</strong><p>{c.s.settings.stiRepaired?'Você informou que o STI foi reparado.':'O ciclismo atual permanece como na planilha.'}</p></div><input aria-label="Reparo do STI concluído" type="checkbox" checked={c.s.settings.stiRepaired} disabled={c.busy} onChange={e=>c.save('settings',{...c.s.settings,stiRepaired:e.target.checked})}/></label><Notice>Informar o reparo não altera a carga de ciclismo. Sextas e sábados continuam exclusivos de musculação; domingos mantêm os simulados progressivos e suas descargas.</Notice></section><section className="card spaced"><SectionTitle title="Prontidão para 31/12" sub="Reavaliar entre 13 e 20 de dezembro"/><div className="readiness-row"><Footprints size={19}/><span>Maior corrida registrada</span><strong>{fmt(runMax,1)} km</strong></div><div className="readiness-row"><Bike size={19}/><span>Maior pedal registrado</span><strong>{fmt(bikeMax,1)} km</strong></div><p className="muted">Essas distâncias isoladas não comprovam prontidão para 90 + 21,1 km. Avaliar longões, sintomas, recuperação, abastecimento e orientação clínica. A fonte prevê alternativas se a preparação for insuficiente.</p></section></div></div><section className="card spaced"><SectionTitle title="Histórico de decisões" sub="Rastreabilidade de cada alteração ou recusa."/>{c.s.decisions.length?<div className="decision-list">{c.s.decisions.slice().reverse().map((d,i)=><div key={i}><span className="soft-icon green"><ShieldCheck size={18}/></span><div><strong>{d.title}</strong><p>{d.reason}</p><small>{new Date(d.createdAt).toLocaleString('pt-BR')} · {d.status==='approved'?'Aprovado':'Recusado'} · {dateFmt(d.date)}</small></div>{c.s.overrides.some(o=>o.sessionId===d.sessionId)&&d.status==='approved'&&<button className="text-btn" disabled={c.busy} onClick={()=>c.save('undo',{sessionId:d.sessionId})}>Restaurar original</button>}</div>)}</div>:<p className="muted">Você ainda não aprovou nem recusou adaptações.</p>}</section><section className="card spaced"><SectionTitle title="Regras e orientações originais"/><div className="table-scroll"><table><thead><tr><th>Tema</th><th>Situação</th><th>Decisão / ação da planilha</th></tr></thead><tbody>{rules.map((r,i)=><tr key={i}>{r.map((v,j)=><td key={j}>{str(v)}</td>)}</tr>)}</tbody></table></div></section></>;}

function DataPage({c,install}:{c:Ctx;install:any}){const [raw,setRaw]=useState('Calendario'),[sourceIndex,setSourceIndex]=useState(-1),[exporting,setExporting]=useState(false),[csv,setCsv]=useState<'training'|'strength'|'nutrition'>('training'),[err,setErr]=useState(''),source=c.s.source,rawSource=sourceIndex<0?source:c.s.archives?.[sourceIndex]?.source||source,validation=validateSource(source);async function out(type:string){setErr('');setExporting(true);try{const w=await import('@/lib/workbook');if(type==='xlsx')w.exportBackup(c.s);else w.exportCsv(c.s,csv);}catch(e){setErr((e as Error).message);}finally{setExporting(false);}}return <><div className="two-column"><section className="card"><div className="data-icon"><FileSpreadsheet size={25}/></div><SectionTitle title="Seu plano está aqui" sub={source.filename}/><div className="data-stats"><div><strong>{source.sheets.length}</strong><span>abas preservadas</span></div><div><strong>{sessions(source).length}</strong><span>sessões com data</span></div><div><strong>{sheetRows(source,'Paces por Corrida').slice(1).filter(r=>dateKey(r[0])).length}</strong><span>corridas detalhadas</span></div></div><p className="muted">As abas originais permanecem acessíveis integralmente abaixo. Ajustes aprovados ficam separados da fonte.</p><div className="inline-actions"><Btn onClick={()=>c.open({type:'import'})}><Upload size={16}/>Importar XLSX</Btn></div></section><section className="card"><SectionTitle title="Backup e exportação" sub="Leve seu histórico completo para onde quiser."/><p className="muted">O backup XLSX inclui todas as abas originais, treinos, séries, refeições, check-ins, ajustes e decisões. Importe-o para restaurar o estado completo.</p><Btn disabled={exporting} onClick={()=>out('xlsx')}>{exporting?<LoaderCircle size={16} className="spin"/>:<ArrowDownToLine size={16}/>}Baixar backup completo · XLSX</Btn><div className="csv-actions"><select aria-label="Dados para CSV" value={csv} onChange={e=>setCsv(e.target.value as any)}><option value="training">Treinos</option><option value="strength">Séries de musculação</option><option value="nutrition">Refeições</option></select><Btn secondary disabled={exporting} onClick={()=>out('csv')}>Exportar CSV</Btn></div><small className="muted">CSV é uma exportação de consulta. Para restaurar tudo, use o backup XLSX.</small>{err&&<p className="form-error" role="alert">{err}</p>}</section><section className="card"><SectionTitle title="Instale no seu celular" sub="Acesso direto à sua rotina."/><p className="muted">Android: menu do navegador → Instalar aplicativo. iPhone: abra no Safari → Compartilhar → Adicionar à Tela de Início.</p>{install&&<Btn onClick={()=>install.prompt()}><Plus size={16}/>Instalar STRIDE</Btn>}<Notice>Seus registros ficam no banco deste navegador e podem ser consultados e alterados offline após a primeira abertura completa. Atualizar o app preserva o banco. Exportar backups XLSX protege contra troca de telefone, desinstalação ou limpeza dos dados do site. A versão Pages não sincroniza automaticamente com a versão anterior nem com outros aparelhos.</Notice></section><section className="card"><SectionTitle title="Preferências"/><Field label="Fuso horário para identificar hoje"><select value={c.s.settings.timezone} disabled={c.busy} onChange={e=>c.save('settings',{...c.s.settings,timezone:e.target.value})}><option value="America/Sao_Paulo">Recife / Brasília</option><option value="America/Manaus">Manaus</option><option value="America/Rio_Branco">Rio Branco</option><option value="Europe/Lisbon">Lisboa</option><option value="UTC">UTC</option></select></Field><div className="privacy-line"><ShieldCheck size={20}/><div><strong>Dados no seu aparelho</strong><p>Registros armazenados somente neste aparelho, com gravação protegida contra alterações concorrentes entre abas. Nenhum dado de treino é enviado ao GitHub.</p></div></div></section></div><section className="card spaced"><SectionTitle title="Análise da planilha" sub="Pontos de atenção identificados sem alterar a fonte."/>{validation.warnings.length?validation.warnings.map((v,i)=><div key={i} className="source-warning"><AlertTriangle size={17}/><p>{v}</p></div>):<Notice>Nenhuma inconsistência estrutural detectada.</Notice>}<p className="muted">Calendario contém uma linha vazia final, ignorada na agenda e mantida na fonte. Não há fórmulas no arquivo inicial. Em S10, Resumo Semanal menciona longão de 4 km; o calendário apresenta o evento condicional em 31/12. Nenhuma corrida extra foi criada.</p><p className="muted">Em 29/12, a aba de paces também diverge da descrição do calendário sobre aquecimento e desaquecimento. A orientação de RPE de tiros permanece registrada, embora o dia seja de descarga. Revise esses pontos antes da sessão.</p></section><section className="card spaced"><div className="source-version"><Field label="Versão da fonte"><select aria-label="Versão da fonte" value={sourceIndex} onChange={e=>{const i=Number(e.target.value);setSourceIndex(i);setRaw((i<0?source:c.s.archives![i].source).sheets[0].name);}}><option value={-1}>Plano atual · {source.filename}</option>{c.s.archives?.map((a,i)=><option value={i} key={i}>Arquivada em {new Date(a.archivedAt).toLocaleString('pt-BR')} · {a.source.filename}</option>)}</select></Field></div><SectionTitle title="Fonte original, sem cortes" sub="Todas as datas, paces, exercícios e orientações alimentares." action={<select aria-label="Aba da planilha" value={raw} onChange={e=>setRaw(e.target.value)}>{rawSource.sheets.map(sh=><option key={sh.name}>{sh.name}</option>)}</select>}/><div className="table-scroll raw-table"><table><thead><tr>{sheetRows(rawSource,raw)[0]?.map((v,i)=><th key={i}>{str(v)||`Coluna ${i+1}`}</th>)}</tr></thead><tbody>{sheetRows(rawSource,raw).slice(1).map((r,i)=><tr key={i}>{r.map((v,j)=><td key={j}>{str(v)}</td>)}</tr>)}</tbody></table></div></section></>;}

function ModalHost({modal,c,close}:{modal:NonNullable<Modal>;c:Ctx;close:()=>void}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{const el=ref.current;el?.showModal();const prev=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.body.style.overflow=prev;};},[]);const titles={training:'Registrar treino',strength:'Registrar exercício',meal:'Registrar refeição',checkin:'Seu check-in de recuperação',session:'Detalhes do dia',import:'Importar planilha',register:'O que você quer registrar?',delete:'Excluir registro'};return <dialog ref={ref} className={'modal '+(modal.type==='session'||modal.type==='import'?'wide-modal':'')} onCancel={e=>{if(c.busy)e.preventDefault();else close();}} onClick={e=>{if(e.target===e.currentTarget&&!c.busy)close();}}><div className="modal-inner"><div className="modal-header"><div><span className="eyebrow">SEU TREINAMENTO</span><h2>{titles[modal.type]}</h2></div><button className="icon-btn" aria-label="Fechar janela" disabled={c.busy} onClick={close}><X size={22}/></button></div>{c.error&&<p className="form-error" role="alert">{c.error}</p>}{modal.type==='register'?<div className="register-options">{[{type:'training',icon:Bike,title:'Treino realizado',sub:'Corrida, ciclismo e atividades'},{type:'strength',icon:Dumbbell,title:'Séries de musculação',sub:'Exercício, repetições e carga'},{type:'meal',icon:Utensils,title:'Refeição e abastecimento',sub:'Calorias, macros e hidratação'},{type:'checkin',icon:Heart,title:'Recuperação do dia',sub:'Sono, disposição e dores'}].map(x=><button key={x.type} onClick={()=>c.open({type:x.type as any})}><span className="soft-icon green"><x.icon size={23}/></span><div><strong>{x.title}</strong><small>{x.sub}</small></div><ArrowRight size={18}/></button>)}</div>:modal.type==='training'?<TrainingForm c={c} data={modal.data} close={close}/>:modal.type==='strength'?<StrengthForm c={c} data={modal.data} close={close}/>:modal.type==='meal'?<MealForm c={c} data={modal.data} close={close}/>:modal.type==='checkin'?<CheckinForm c={c} close={close}/>:modal.type==='session'?<SessionDetail c={c} p={modal.data}/>:modal.type==='import'?<ImportForm c={c} close={close}/>:<DeleteForm c={c} data={modal.data} close={close}/>}</div></dialog>;}
function SaveButton({busy,label='Salvar registro'}:{busy:boolean;label?:string}){return <button className="btn" type="submit" disabled={busy}>{busy?<LoaderCircle size={17} className="spin"/>:<Check size={17}/>} {busy?'Salvando…':label}</button>;}
function TrainingForm({c,data,close}:{c:Ctx;data?:any;close:()=>void}){const l:TrainingLog|undefined=data?.log,initial:Session|undefined=data?.session,[date,setDate]=useState(l?.date||initial?.date||c.date),[session,setSession]=useState(l?.sessionId||initial?.id||''),[kind,setKind]=useState(l?.kind||data?.kind||(initial?(titleKind(initial)==='brick'?'bike':titleKind(initial)==='rest'?'other':titleKind(initial)):'run')),[status,setStatus]=useState(l?.status||'completed'),[distance,setDistance]=useState(l?.distance?.toString()||''),[duration,setDuration]=useState(l?.duration?.toString()||'');const ps=sessions(c.s.source).filter(p=>p.date===date);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget),d={id:l?.id||uid(),date,sessionId:session,kind,status,distance:num(distance),duration:num(duration),hr:fd.get('hr')?num(fd.get('hr')):null,rpe:fd.get('rpe')?num(fd.get('rpe')):null,pain:num(fd.get('pain')),notes:str(fd.get('notes')),createdAt:l?.createdAt||''};if(await c.save('training',d))close();}return <form onSubmit={submit}><div className="form-grid"><Field label="Data"><input required type="date" value={date} onChange={e=>{setDate(e.target.value);setSession('');}}/></Field><Field label="Modalidade"><select value={kind} onChange={e=>setKind(e.target.value)}><option value="run">Corrida</option><option value="bike">Ciclismo</option><option value="strength">Musculação</option><option value="other">Outra atividade</option></select></Field><div className="full"><Field label="Vincular ao planejamento"><select value={session} onChange={e=>setSession(e.target.value)}><option value="">Atividade extra (sem vínculo)</option>{ps.map(p=><option key={p.id} value={p.id}>{p.title}</option>)}</select></Field></div><Field label="Situação"><select value={status} onChange={e=>setStatus(e.target.value as any)}><option value="completed">Realizado</option><option value="skipped">Não realizado</option></select></Field><Field label="Duração · minutos"><input type="number" min={status==='completed'?'0.1':'0'} max="3000" step="0.1" required={status==='completed'} placeholder="Ex.: 45" value={duration} onChange={e=>setDuration(e.target.value)}/></Field>{kind!=='strength'&&<Field label="Distância · km"><input type="number" min="0" max="1000" step="0.01" placeholder="Ex.: 6,5" value={distance} onChange={e=>setDistance(e.target.value)}/></Field>}<Field label="Frequência cardíaca média · bpm"><input name="hr" type="number" min="20" max="260" placeholder="Opcional" defaultValue={l?.hr??''}/></Field><Field label="Percepção de esforço · RPE 1–10"><input name="rpe" type="number" min="1" max="10" step="1" placeholder="Opcional" defaultValue={l?.rpe??''}/></Field><Field label="Dor · 0–10"><input name="pain" required type="number" min="0" max="10" step="1" defaultValue={l?.pain??0}/></Field></div><div className="calculated-metrics"><div><small>PACE CALCULADO</small><strong>{pace(num(distance),num(duration))}<span> /km</span></strong></div><div><small>VELOCIDADE MÉDIA</small><strong>{num(distance)>0&&num(duration)>0?fmt(speed(num(distance),num(duration)),1):'—'}<span> km/h</span></strong></div></div>{session&&ps.find(p=>p.id===session)?.brick&&<Notice>Simulado: registre bike e corrida separadamente, vinculando ambas à mesma sessão. A duração de cada modalidade não deve incluir a transição. Anote a transição nas observações.</Notice>}<Field label="Dores, local e observações"><textarea name="notes" maxLength={2000} rows={3} placeholder="Como foi? Onde sentiu dor? Condições do percurso, pausas…" defaultValue={l?.notes||''}/></Field>{date>c.now&&<Notice tone="warning">Você está registrando em uma data futura: {dateFmt(date)}. Esses dados só entram na evolução quando a data chegar.</Notice>}<div className="form-actions"><Btn secondary onClick={close} disabled={c.busy}>Cancelar</Btn><SaveButton busy={c.busy}/></div></form>;}
function StrengthForm({c,data,close}:{c:Ctx;data?:any;close:()=>void}){const l:StrengthLog|undefined=data?.log,r=data?.exercise;const [exercise,setExercise]=useState(l?.exercise||str(r?.[1])),[sets,setSets]=useState<{reps:string;kg:string}[]>(l?l.sets.map(s=>({reps:String(s.reps),kg:String(s.kg)})):Array.from({length:num(r?.[2])||3},()=>({reps:'',kg:''})));const exercises=Array.from(new Set(sheetRows(c.s.source,'Musculacao').slice(1).map(r=>str(r[1]))));async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);if(await c.save('strength',{id:l?.id||uid(),date:f.get('date'),exercise,sets:sets.map(x=>({reps:num(x.reps),kg:num(x.kg)})),notes:str(f.get('notes')),createdAt:l?.createdAt||''}))close();}return <form onSubmit={submit}><div className="form-grid"><Field label="Data"><input required type="date" name="date" defaultValue={l?.date||c.date}/></Field><Field label="Exercício"><input list="exercises" maxLength={150} required value={exercise} onChange={e=>setExercise(e.target.value)} placeholder="Escolha ou digite"/><datalist id="exercises">{exercises.map(x=><option key={x} value={x}/>)}</datalist></Field></div>{r&&<Notice>Prescrito: {r[2]} × {r[3]} · {r[4]} · Descanso {r[5]}</Notice>}<div className="set-head"><span>SÉRIE</span><span>REPETIÇÕES</span><span>CARGA · KG</span><span/></div>{sets.map((x,i)=><div className="set-row" key={i}><span>{String(i+1).padStart(2,'0')}</span><input aria-label={`Repetições série ${i+1}`} type="number" min="1" max="200" step="1" required value={x.reps} onChange={e=>setSets(sets.map((s,j)=>j===i?{...s,reps:e.target.value}:s))} placeholder={str(r?.[3])||'Reps'}/><input aria-label={`Carga série ${i+1}`} type="number" min="0" max="600" step="0.25" required value={x.kg} onChange={e=>setSets(sets.map((s,j)=>j===i?{...s,kg:e.target.value}:s))} placeholder="0"/><button type="button" className="icon-btn" aria-label={`Remover série ${i+1}`} disabled={sets.length===1} onClick={()=>setSets(sets.filter((_,j)=>j!==i))}><X size={15}/></button></div>)}<button className="text-btn add-set" type="button" disabled={sets.length>=30} onClick={()=>setSets([...sets,{reps:sets[sets.length-1].reps,kg:sets[sets.length-1].kg}])}><Plus size={16}/> Adicionar série</button><div className="calculated-metrics"><div><small>VOLUME TOTAL</small><strong>{fmt(sets.reduce((a,s)=>a+num(s.reps)*num(s.kg),0))}<span> kg</span></strong></div><small>Carga externa registrada. Em exercícios sem peso, informe 0 kg.</small></div><Field label="Observações"><textarea name="notes" maxLength={2000} rows={2} defaultValue={l?.notes||''} placeholder="RIR, técnica, desconforto…"/></Field><div className="form-actions"><Btn secondary disabled={c.busy} onClick={close}>Cancelar</Btn><SaveButton busy={c.busy}/></div></form>;}
function MealForm({c,data:m,close}:{c:Ctx;data?:Meal;close:()=>void}){const [protein,setProtein]=useState(String(m?.protein??'')),[carbs,setCarbs]=useState(String(m?.carbs??'')),[fat,setFat]=useState(String(m?.fat??''));async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);if(await c.save('meal',{id:m?.id||uid(),date:f.get('date'),name:str(f.get('name')),timing:str(f.get('timing')),calories:f.get('calories')?num(f.get('calories')):null,protein:num(protein),carbs:num(carbs),fat:num(fat),water:num(f.get('water')),gi:str(f.get('gi')),notes:str(f.get('notes')),createdAt:m?.createdAt||''}))close();}return <form onSubmit={submit}><div className="form-grid"><Field label="Data"><input required name="date" type="date" defaultValue={m?.date||c.date}/></Field><Field label="Momento"><select name="timing" defaultValue={m?.timing||'Refeição'}>{['Refeição','Pré-treino','Intra-treino','Pós-treino','Lanche'].map(v=><option key={v}>{v}</option>)}</select></Field><div className="full"><Field label="Refeição / alimentos"><input required maxLength={150} name="name" defaultValue={m?.name||''} placeholder="Ex.: cuscuz, ovos e banana"/></Field></div><Field label="Proteína · g"><input required type="number" min="0" max="20000" step="0.1" value={protein} onChange={e=>setProtein(e.target.value)} placeholder="0"/></Field><Field label="Carboidratos · g"><input required type="number" min="0" max="20000" step="0.1" value={carbs} onChange={e=>setCarbs(e.target.value)} placeholder="0"/></Field><Field label="Gorduras · g"><input required type="number" min="0" max="20000" step="0.1" value={fat} onChange={e=>setFat(e.target.value)} placeholder="0"/></Field><Field label="Calorias informadas · opcional" hint="Se vazio, calculamos pelos macros (4/4/9)."><input name="calories" type="number" min="0" max="20000" step="1" defaultValue={m?.calories??''} placeholder={`${fmt(macrosKcal({protein:num(protein),carbs:num(carbs),fat:num(fat)}))} kcal calculadas`}/></Field><Field label="Líquidos · mL"><input name="water" type="number" min="0" max="20000" step="10" defaultValue={m?.water??0}/></Field><Field label="Sintomas gastrointestinais"><input name="gi" maxLength={500} defaultValue={m?.gi||''} placeholder="Nenhum, náusea, desconforto…"/></Field></div><Field label="Observações"><textarea name="notes" maxLength={2000} rows={2} defaultValue={m?.notes||''}/></Field><Notice>Registre valores de rótulos ou da sua orientação nutricional. O app não estima macros a partir do nome do alimento nem cria uma nova meta calórica.</Notice><div className="form-actions"><Btn secondary disabled={c.busy} onClick={close}>Cancelar</Btn><SaveButton busy={c.busy}/></div></form>;}
function CheckinForm({c,close}:{c:Ctx;close:()=>void}){const old=c.s.checkins.find(x=>x.date===c.now),[recovery,setRecovery]=useState(old?.recovery||3),[pain,setPain]=useState(old?.pain||0);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);if(await c.save('checkin',{date:c.now,sleep:num(f.get('sleep')),recovery,pain,alert:f.get('alert')==='on',notes:str(f.get('notes')),updatedAt:''}))close();}return <form onSubmit={submit}><p className="muted">{dateFmt(c.now,{weekday:'long',day:'numeric',month:'long'})}</p><Field label="Quantas horas você dormiu?"><input required name="sleep" type="number" min="0" max="24" step="0.5" defaultValue={old?.sleep??''} placeholder="Ex.: 7,5"/></Field><Field label="Como está sua recuperação?"><div className="recovery-options">{[1,2,3,4,5].map(n=><button key={n} type="button" className={n===recovery?'selected':''} onClick={()=>setRecovery(n)}><strong>{n}</strong><span>{['','Muito baixa','Baixa','Regular','Boa','Ótima'][n]}</span></button>)}</div></Field><Field label={`Dor agora · ${pain}/10`}><input type="range" min="0" max="10" value={pain} onChange={e=>setPain(num(e.target.value))}/></Field><label className="checkbox-field"><input type="checkbox" name="alert" defaultChecked={old?.alert}/><span>Tive sinal de alerta: dor torácica, desmaio, confusão, crise ou sintoma anormal importante.</span></label><Field label="Como você está se sentindo?"><textarea name="notes" rows={3} maxLength={2000} defaultValue={old?.notes||''} placeholder="Dor localizada, fadiga, disposição…"/></Field><Notice tone="warning">Diante de sinais de alerta, interrompa a atividade e procure avaliação conforme a gravidade. Não espere a aprovação de um ajuste no aplicativo.</Notice><div className="form-actions"><Btn secondary disabled={c.busy} onClick={close}>Cancelar</Btn><SaveButton busy={c.busy} label="Salvar check-in"/></div></form>;}
function SessionDetail({c,p}:{c:Ctx;p:Session}){const e=effective(c.s,p),pd=p.paceDetails,nutrition=sheetRows(c.s.source,'Nutricao por Data').slice(1).find(r=>dateKey(r[0])===p.date),exercises=sheetRows(c.s.source,'Musculacao').slice(1).filter(r=>r[0]===p.day);return <div><div className="detail-heading"><Badge>{p.week} · {dateFmt(p.date,{weekday:'long',day:'numeric',month:'long'})}</Badge><h3>{p.title}</h3><p>{p.prescription}</p><p className="muted">{p.intensity}</p>{p.strength!=='—'&&<p>{p.strength}</p>}</div>{e.factor!==1&&<Notice tone="warning">Ajuste aprovado: {e.factor===0?'pausado':`${Math.round((e.factor-1)*100)}% no volume`}. {e.minutes} min · {e.runKm!==null?`${fmt(e.runKm,2)} km corrida`:''}. Os detalhes abaixo são a fonte original. {e.factor<1&&e.factor>0?"No ajuste por fadiga, mantenha esforço confortável e não persiga os paces dos tiros originais.":""}</Notice>}{pd&&<section className="detail-section"><h3>Corrida · paces individualizados</h3><div className="pace-target"><div><small>PACE PRINCIPAL</small><strong>{pd[7]}<span> /km</span></strong></div><div><small>TEMPO-ALVO ORIGINAL</small><strong>{pd[12]}–{pd[13]}<span> min</span></strong></div></div><div className="detail-rows">{[['Aquecimento',pd[4],pd[5]],['Bloco principal',pd[6],pd[7]],['Recuperação',pd[8],pd[9]],['Desaquecimento',pd[10],pd[11]]].map(([l,v,pace])=><div key={l}><strong>{l}</strong><span>{v}</span><small>{pace}{String(pace).includes(':')?' /km':''}</small></div>)}</div><Notice>{pd[15]}</Notice>{p.date==='2026-12-29'&&<Notice tone="warning">Divergência original em 29/12: tempo-alvo 19–24 min, calendário 45 min e blocos com outra soma. Fonte preservada; confirmar duração e esforço antes de realizar.</Notice>}<p className="muted">RPE original: {pd[14]}. O tempo do brick considera somente corrida, sem bike e transição.</p></section>}{p.brick&&<section className="detail-section"><h3>Simulado e evento</h3><p>{p.brick[2]} km bike + {p.brick[3]} km corrida · {p.brick[4]}</p><p>Intra-treino original: {p.brick[5]}</p><Notice>{p.brick[6]}</Notice></section>}{exercises.length>0&&<section className="detail-section"><h3>Musculação prescrita</h3>{exercises.map((r,i)=><div className="compact-exercise" key={i}><strong>{r[1]}</strong><span>{r[2]} × {r[3]} · {r[4]} · {r[5]}</span></div>)}</section>}{nutrition&&<section className="detail-section"><h3>Nutrição nesta data</h3><DailyNutrition s={c.s} date={p.date}/></section>}<section className="detail-section"><h3>Registros deste treino</h3><LogList c={c} logs={c.s.logs.filter(l=>l.sessionId===p.id)}/></section><div className="form-actions"><Btn onClick={()=>{c.select(p.date);c.open({type:'training',data:{session:p}});}}><Plus size={17}/>Registrar treino</Btn></div></div>;}
function ImportForm({c,close}:{c:Ctx;close:()=>void}){const [parsed,setParsed]=useState<any>(null),[parsing,setParsing]=useState(false),[err,setErr]=useState(''),[selected,setSelected]=useState('Calendario'),[confirm,setConfirm]=useState(false);async function parse(file?:File){if(!file)return;setParsing(true);setErr('');setParsed(null);setConfirm(false);try{const w=await import('@/lib/workbook');const v=await w.parseWorkbook(file);setParsed(v);setSelected(v.source.sheets[0]?.name||'Calendario');}catch(e){setErr('Arquivo não importado: '+(e as Error).message);}finally{setParsing(false);}}const sh=parsed?.source.sheets.find((s:any)=>s.name===selected);async function submit(){if(!parsed||!confirm)return;if(await c.save(parsed.backup?'restore':'import',parsed.backup||parsed.source))close();}return <div><p className="muted">Selecione uma planilha no formato do plano original ou um backup completo do STRIDE. Você revisa os dados antes de confirmar.</p><label className="upload-zone" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();parse(e.dataTransfer.files[0]);}}><span className="upload-icon">{parsing?<LoaderCircle size={29} className="spin"/>:<Upload size={29}/>}</span><strong>{parsing?'Analisando todas as abas…':'Escolher planilha XLSX'}</strong><span>Toque para selecionar ou solte o arquivo aqui · até 10 MB</span><input aria-label="Selecionar planilha XLSX" type="file" accept=".xlsx" disabled={parsing||c.busy} onChange={e=>parse(e.target.files?.[0])}/></label>{err&&<p className="form-error" role="alert">{err}</p>}{parsed&&<><div className="import-summary"><div><CheckCheck size={22}/><div><strong>{parsed.source.filename}</strong><small>{parsed.source.sheets.length} abas · {sessions(parsed.source).length} sessões com data · {parsed.backup?'Backup completo detectado':'Plano detectado'}</small></div></div><Badge tone={parsed.validation.errors.length?'red':'green'}>{parsed.validation.errors.length?'Revisar erros':'Estrutura válida'}</Badge></div>{parsed.validation.errors.map((e:string,i:number)=><p className="form-error" key={i}>{e}</p>)}{parsed.validation.warnings.map((e:string,i:number)=><div className="source-warning" key={i}><AlertTriangle size={15}/><p>{e}</p></div>)}<div className="import-tabs"><label className="field"><span>Pré-visualizar aba</span><select value={selected} onChange={e=>setSelected(e.target.value)}>{parsed.source.sheets.map((sh:any)=><option key={sh.name}>{sh.name}</option>)}</select></label><small>{sh?.rows.length||0} linhas · {Math.max(0,...(sh?.rows||[]).map((r:any[])=>r.length))} colunas</small></div><div className="table-scroll import-preview"><table><thead><tr>{sh?.rows[0]?.map((v:any,i:number)=><th key={i}>{str(v)}</th>)}</tr></thead><tbody>{sh?.rows.slice(1,11).map((r:any[],i:number)=><tr key={i}>{r.map((v,j)=><td key={j}>{str(v)}</td>)}</tr>)}</tbody></table></div><small className="muted">Prévia das primeiras 10 linhas. Todas as linhas válidas serão importadas; a fonte completa continuará acessível.</small>{parsed.backup&&<Notice tone="warning">Restaurar substitui o plano e os registros atuais pelo conteúdo do backup ({parsed.backup.logs.length} treinos, {parsed.backup.strength.length} exercícios e {parsed.backup.meals.length} refeições). Faça um backup atual antes de prosseguir.</Notice>}<label className="checkbox-field"><input type="checkbox" checked={confirm} onChange={e=>setConfirm(e.target.checked)}/><span>{parsed.backup?'Revisei e autorizo substituir os dados atuais por este backup.':'Revisei a prévia. Autorizo atualizar o plano, preservar meus registros e arquivar a fonte anterior (até 8 versões).'}</span></label></>}<div className="form-actions"><Btn secondary disabled={c.busy} onClick={close}>Cancelar</Btn><Btn disabled={c.busy||parsing||!parsed||!confirm||!!parsed?.validation.errors.length} onClick={submit}>{c.busy?<LoaderCircle size={17} className="spin"/>:<Check size={17}/>}Confirmar {parsed?.backup?'restauração':'importação'}</Btn></div></div>;}
function DeleteForm({c,data,close}:{c:Ctx;data:any;close:()=>void}){return <div><p>Excluir {data.label}? Esta ação remove o registro do banco local deste aparelho. Um backup exportado anteriormente continua intacto.</p><div className="form-actions"><Btn secondary onClick={close} disabled={c.busy}>Cancelar</Btn><button className="btn danger-btn" disabled={c.busy} onClick={async()=>{if(await c.save('delete',data))close();}}><Trash2 size={16}/>Excluir registro</button></div></div>;}
